1	package cli
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"os"
8		"sort"
9		"strconv"
10		"strings"
11	
12		"github.com/spf13/cobra"
13	)
14	
15	// evalTask is one held-out retrieval task. Task is the query an agent would
16	// issue; Relevant, when present, is the ground-truth set of fact ids that
17	// genuinely help the task (enables deterministic precision/recall). Without
18	// labels, --judge has an agent decide relevance per surfaced fact.
19	type evalTask struct {
20		ID        string   `json:"id"`
21		Task      string   `json:"task"`
22		Branch    string   `json:"branch,omitempty"`
23		QueryType string   `json:"query_type,omitempty"`
24		K         int      `json:"k,omitempty"`
25		Relevant  []string `json:"relevant,omitempty"`
26	}
27	
28	// evalTaskResult is the per-task measurement. The headline metric is
29	// UsefulPer1k — relevant facts surfaced per 1,000 tokens spent — which captures
30	// the Appendix D agent constraint (value per token, not fact count).
31	type evalTaskResult struct {
32		ID               string  `json:"id"`
33		Task             string  `json:"task"`
34		QueryType        string  `json:"query_type,omitempty"`
35		Surfaced         int     `json:"surfaced"`
36		Tokens           int     `json:"tokens"`
37		RelevantSurfaced int     `json:"relevant_surfaced"`
38		Precision        float64 `json:"precision"`
39		Recall           float64 `json:"recall,omitempty"`
40		UsefulPer1k      float64 `json:"useful_per_1k"`
41		Labeled          bool    `json:"labeled"`
42	}
43	
44	// evalStratum aggregates metrics for one query-type stratum.
45	type evalStratum struct {
46		Tasks           int     `json:"tasks"`
47		MeanTokens      float64 `json:"mean_tokens"`
48		MeanPrecision   float64 `json:"mean_precision"`
49		MeanUsefulPer1k float64 `json:"mean_useful_per_1k"`
50	}
51	
52	type evalSummary struct {
53		Arm             string                 `json:"arm,omitempty"`
54		Tasks           int                    `json:"tasks"`
55		MeanTokens      float64                `json:"mean_tokens"`
56		MeanPrecision   float64                `json:"mean_precision"`
57		MeanUsefulPer1k float64                `json:"mean_useful_per_1k"`
58		ByStratum       map[string]evalStratum `json:"by_stratum,omitempty"`
59		SurfacedByKind  map[string]int         `json:"surfaced_by_kind,omitempty"`
60		Results         []evalTaskResult       `json:"results"`
61	}
62	
63	// estimateTokens is a deterministic ~4-chars-per-token estimate over the text
64	// an agent would actually load (fact text plus its paths). It is a relative
65	// measure for comparing retrieval configurations, not an exact tokenizer.
66	func estimateTokens(facts []factRecord) int {
67		chars := 0
68		for _, f := range facts {
69			chars += len(f.Text) + len(strings.Join(f.Paths, ",")) + 4 // small per-fact framing
70		}
71		return (chars + 3) / 4
72	}
73	
74	// evalMetrics computes the per-task metrics given the surfaced facts and the set
75	// of relevant fact ids. totalRelevant is the size of the ground-truth relevant
76	// set (for recall); pass 0 when relevance came from a judge (recall undefined).
77	func evalMetrics(surfaced []factRecord, relevant map[string]struct{}, totalRelevant int) evalTaskResult {
78		res := evalTaskResult{Surfaced: len(surfaced), Tokens: estimateTokens(surfaced)}
79		for _, f := range surfaced {
80			if _, ok := relevant[f.ID]; ok {
81				res.RelevantSurfaced++
82			}
83		}
84		if res.Surfaced > 0 {
85			res.Precision = float64(res.RelevantSurfaced) / float64(res.Surfaced)
86		}
87		if totalRelevant > 0 {
88			res.Recall = float64(res.RelevantSurfaced) / float64(totalRelevant)
89		}
90		if res.Tokens > 0 {
91			res.UsefulPer1k = float64(res.RelevantSurfaced) / (float64(res.Tokens) / 1000.0)
92		}
93		return res
94	}
95	
96	func summarizeEval(results []evalTaskResult) evalSummary {
97		s := evalSummary{Tasks: len(results), Results: results}
98		if len(results) == 0 {
99			return s
100		}
101		var tok, prec, useful float64
102		strata := map[string][]evalTaskResult{}
103		for _, r := range results {
104			tok += float64(r.Tokens)
105			prec += r.Precision
106			useful += r.UsefulPer1k
107			if r.QueryType != "" {
108				strata[r.QueryType] = append(strata[r.QueryType], r)
109			}
110		}
111		n := float64(len(results))
112		s.MeanTokens = tok / n
113		s.MeanPrecision = prec / n
114		s.MeanUsefulPer1k = useful / n
115		if len(strata) > 0 {
116			s.ByStratum = make(map[string]evalStratum, len(strata))
117			for qt, rs := range strata {
118				var t, p, u float64
119				for _, r := range rs {
120					t += float64(r.Tokens)
121					p += r.Precision
122					u += r.UsefulPer1k
123				}
124				m := float64(len(rs))
125				s.ByStratum[qt] = evalStratum{Tasks: len(rs), MeanTokens: t / m, MeanPrecision: p / m, MeanUsefulPer1k: u / m}
126			}
127		}
128		return s
129	}
130	
131	// --- agent judge ----------------------------------------------------------
132	
133	// judgePrompt instructs the agent to mark which surfaced facts are relevant to
134	// a task. Like the other agent prompts it must not begin with a dash.
135	func judgePrompt() string {
136		return `You assess whether retrieved repository facts are relevant and useful for a TASK.
137	On stdin you receive a TASK line followed by a numbered list of FACTS. For each
138	fact, decide if it would genuinely help an engineer or agent carry out the task.
139	
140	Output exactly one line per fact, in fact-number order:
141	
142	    <fact#> <yes|no>
143	
144	Output only these lines. No prose.`
145	}
146	
147	func judgeInput(task string, facts []factRecord) []byte {
148		var b strings.Builder
149		fmt.Fprintf(&b, "TASK: %s\n\nFACTS\n", task)
150		for i, f := range facts {
151			fmt.Fprintf(&b, "%d [%s] %s\n", i+1, strings.Join(f.Paths, ","), f.Text)
152		}
153		return []byte(b.String())
154	}
155	
156	// parseJudgeOutput returns the set of surfaced-fact ids the agent marked
157	// relevant. An unparseable or missing line defaults to not-relevant, so a judge
158	// hiccup never inflates the usefulness metric.
159	func parseJudgeOutput(output string, facts []factRecord) map[string]struct{} {
160		relevant := map[string]struct{}{}
161		for _, raw := range strings.Split(output, "\n") {
162			fields := strings.Fields(strings.TrimSpace(raw))
163			if len(fields) < 2 {
164				continue
165			}
166			n, err := strconv.Atoi(fields[0])
167			if err != nil || n < 1 || n > len(facts) {
168				continue
169			}
170			if strings.EqualFold(fields[1], "yes") {
171				relevant[facts[n-1].ID] = struct{}{}
172			}
173		}
174		return relevant
175	}
176	
177	// --- command --------------------------------------------------------------
178	
179	func newFactsEvalCommand(opts Options) *cobra.Command {
180		var (
181			tasksFile    string
182			branch       string
183			k            int
184			judge        bool
185			semantic     bool
186			arm          string
187			expand       bool
188			agent        string
189			agentCommand []string
190			judgeCache   string
191			expandCache  string
192			jsonOut      bool
193			run          distillAgentRunner
194		)
195		cmd := &cobra.Command{
196			Use:   "eval --tasks <file>",
197			Short: "Measure retrieval quality (tokens, precision, useful-facts-per-1k) over held-out tasks",
198			Long: `Eval runs a held-out task set through fact retrieval and reports, per task and
199	in aggregate: facts surfaced, estimated tokens, precision, recall, and
200	useful-facts-per-1k-tokens (the headline agent metric).
201	
202	The tasks file is a JSON array:
203	  [{"id":"t1","task":"how does X work","branch":"main","k":10,
204	    "relevant":["fact:abc","fact:def"]}]
205	With "relevant" ids, metrics are deterministic. Without them, pass --judge to
206	have the agent decide relevance per surfaced fact.`,
207			Args: cobra.NoArgs,
208			RunE: func(cmd *cobra.Command, args []string) error {
209				if strings.TrimSpace(tasksFile) == "" {
210					return fmt.Errorf("--tasks <file> is required")
211				}
212				tasks, err := loadEvalTasks(tasksFile)
213				if err != nil {
214					return err
215				}
216				repoDir, brainDir, defaultBranch, err := resolveFactsTarget(cmd.Context(), opts, agentSurfaceTarget(opts, nil), branch)
217				if err != nil {
218					return err
219				}
220				resolvedAgent := agent
221				if (judge || expand) && resolvedAgent == "auto" {
222					resolvedAgent = defaultRefreshAgent(cmd.Context(), opts.Runner, repoDir)
223				}
224				var judgeArgs []string
225				if judge {
226					judgeArgs, err = distillAgentCommandArgs(resolvedAgent, agentCommand, judgePrompt())
227					if err != nil {
228						return fmt.Errorf("judge agent: %w", err)
229					}
230					if run == nil {
231						run = execDistillAgent
232					}
233				}
234				var expander queryExpanderFunc
235				expCache := loadExpansionCache(expandCache)
236				if expand {
237					expandArgs, expErr := distillAgentCommandArgs(resolvedAgent, agentCommand, queryExpansionPrompt())
238					if expErr != nil {
239						return fmt.Errorf("expand agent: %w", expErr)
240					}
241					expRun := run
242					if expRun == nil {
243						expRun = execDistillAgent
244					}
245					expander = func(query string) (string, error) {
246						return expandQuery(cmd.Context(), expRun, expandArgs, repoDir, query, expCache)
247					}
248				}
249				var rr *semanticReranker
250				if semantic {
251					rr = newSemanticReranker(defaultEmbedder())
252					if rr == nil {
253						return fmt.Errorf("--semantic requested but the embedding backend is unavailable")
254					}
255				}
256				armFn, err := selectRetrievalArm(arm)
257				if err != nil {
258					return err
259				}
260				results, surfacedByKind, err := runFactsEval(cmd.Context(), opts, brainDir, repoDir, defaultBranch, tasks, k, judge, run, judgeArgs, loadJudgeCache(judgeCache), expander, rr, armFn)
261				if err != nil {
262					return err
263				}
264				if err := expCache.save(); err != nil {
265					return fmt.Errorf("save expansion cache: %w", err)
266				}
267				summary := summarizeEval(results)
268				if arm != "" {
269					summary.Arm = arm
270				}
271				summary.SurfacedByKind = surfacedByKind
272				if jsonOut {
273					return writeJSON(cmd, summary)
274				}
275				printEvalSummary(cmd, summary)
276				return nil
277			},
278		}
279		cmd.Flags().StringVar(&tasksFile, "tasks", "", "Path to the held-out task set (JSON array)")
280		cmd.Flags().StringVar(&branch, "branch", "", "Default branch for tasks that omit one (default: current branch)")
281		cmd.Flags().IntVar(&k, "k", 10, "Facts to retrieve per task")
282		cmd.Flags().BoolVar(&judge, "judge", false, "Use the agent to judge relevance when a task has no labels")
283		cmd.Flags().StringVar(&agent, "agent", "auto", "Judge/expand agent: auto, codex, claude-code, or command")
284		cmd.Flags().StringArrayVar(&agentCommand, "agent-command", nil, "Agent command argv for --agent command")
285		cmd.Flags().StringVar(&judgeCache, "judge-cache", "", "Persist/reuse judge verdicts at this path so re-runs are deterministic and cheap")
286		cmd.Flags().BoolVar(&semantic, "semantic", false, "Rerank with the local embedding backend (RRF fusion of lexical + semantic)")
287		cmd.Flags().StringVar(&arm, "arm", "flat", "Retrieval structure to evaluate: flat | scoped (locus) | scoped-floor | outline")
288		cmd.Flags().BoolVar(&expand, "expand", false, "Expand each task query with agent-generated retrieval terms before recall")
289		cmd.Flags().StringVar(&expandCache, "expand-cache", "", "Persist/reuse query expansions at this path")
290		cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit the summary as JSON")
291		return cmd
292	}
293	
294	// judgeCache persists agent relevance verdicts keyed by "<taskID>\x00<factID>"
295	// so judged evals are repeatable and only new (task, fact) pairs cost an agent
296	// call. It makes judge-based A/Bs deterministic across runs.
297	type judgeCache struct {
298		path    string
299		verdict map[string]bool
300		dirty   bool
301	}
302	
303	func judgeCacheKey(taskID, factID string) string { return taskID + "\x00" + factID }
304	
305	func loadJudgeCache(path string) *judgeCache {
306		c := &judgeCache{path: path, verdict: map[string]bool{}}
307		if strings.TrimSpace(path) == "" {
308			return c
309		}
310		if data, err := os.ReadFile(path); err == nil {
311			_ = json.Unmarshal(data, &c.verdict)
312		}
313		return c
314	}
315	
316	func (c *judgeCache) get(taskID, factID string) (bool, bool) {
317		if c == nil {
318			return false, false
319		}
320		v, ok := c.verdict[judgeCacheKey(taskID, factID)]
321		return v, ok
322	}
323	
324	func (c *judgeCache) set(taskID, factID string, relevant bool) {
325		if c == nil {
326			return
327		}
328		c.verdict[judgeCacheKey(taskID, factID)] = relevant
329		c.dirty = true
330	}
331	
332	func (c *judgeCache) save() error {
333		if c == nil || !c.dirty || strings.TrimSpace(c.path) == "" {
334			return nil
335		}
336		data, err := json.MarshalIndent(c.verdict, "", "  ")
337		if err != nil {
338			return err
339		}
340		return os.WriteFile(c.path, append(data, '\n'), 0o600)
341	}
342	
343	func loadEvalTasks(path string) ([]evalTask, error) {
344		data, err := os.ReadFile(path)
345		if err != nil {
346			return nil, err
347		}
348		var tasks []evalTask
349		if err := json.Unmarshal(data, &tasks); err != nil {
350			return nil, fmt.Errorf("parse tasks file: %w", err)
351		}
352		if len(tasks) == 0 {
353			return nil, fmt.Errorf("tasks file has no tasks")
354		}
355		return tasks, nil
356	}
357	
358	// queryExpanderFunc maps a task query to extra retrieval terms; nil disables
359	// expansion.
360	type queryExpanderFunc func(query string) (string, error)
361	
362	func runFactsEval(ctx context.Context, opts Options, brainDir, repoDir, defaultBranch string, tasks []evalTask, defaultK int, judge bool, run distillAgentRunner, judgeArgs []string, cache *judgeCache, expander queryExpanderFunc, rr *semanticReranker, arm retrievalArm) ([]evalTaskResult, map[string]int, error) {
363		if arm == nil {
364			arm = flatArm
365		}
366		results := make([]evalTaskResult, 0, len(tasks))
367		surfacedByKind := map[string]int{}
368		factsByBranch := map[string][]factRecord{} // load each branch's facts once per run
369		for _, task := range tasks {
370			branch := task.Branch
371			if branch == "" {
372				branch = defaultBranch
373			}
374			k := task.K
375			if k <= 0 {
376				k = defaultK
377			}
378			facts, ok := factsByBranch[branch]
379			if !ok {
380				loaded, err := loadFacts(brainDir, branch)
381				if err != nil {
382					return nil, nil, err
383				}
384				facts = loaded
385				factsByBranch[branch] = facts
386			}
387			query := task.Task
388			if expander != nil {
389				if exp, expErr := expander(task.Task); expErr != nil {
390					return nil, nil, fmt.Errorf("expand task %s: %w", task.ID, expErr)
391				} else {
392					query = expandedQuery(task.Task, exp)
393				}
394			}
395			surfaced := arm(facts, query, k, rr)
396			for _, f := range surfaced {
397				surfacedByKind[factKindOrInferred(f)]++
398			}
399	
400			var relevant map[string]struct{}
401			totalRelevant := 0
402			labeled := len(task.Relevant) > 0
403			if labeled {
404				relevant = make(map[string]struct{}, len(task.Relevant))
405				for _, id := range task.Relevant {
406					relevant[id] = struct{}{}
407				}
408				totalRelevant = len(relevant)
409			} else if judge && len(surfaced) > 0 {
410				judged, jerr := judgeRelevance(ctx, run, repoDir, judgeArgs, task, surfaced, cache)
411				if jerr != nil {
412					return nil, nil, jerr
413				}
414				relevant = judged
415			} else {
416				relevant = map[string]struct{}{}
417			}
418	
419			res := evalMetrics(surfaced, relevant, totalRelevant)
420			res.ID, res.Task, res.QueryType, res.Labeled = task.ID, task.Task, task.QueryType, labeled
421			results = append(results, res)
422		}
423		if err := cache.save(); err != nil {
424			return nil, nil, fmt.Errorf("save judge cache: %w", err)
425		}
426		return results, surfacedByKind, nil
427	}
428	
429	// judgeRelevance returns the set of surfaced-fact ids judged relevant for a
430	// task, consulting the cache first and only asking the agent about the
431	// uncached facts (then recording its verdicts). This makes judged evals cheap
432	// to re-run and deterministic across runs.
433	func judgeRelevance(ctx context.Context, run distillAgentRunner, repoDir string, judgeArgs []string, task evalTask, surfaced []factRecord, cache *judgeCache) (map[string]struct{}, error) {
434		relevant := map[string]struct{}{}
435		var uncached []factRecord
436		for _, f := range surfaced {
437			if v, ok := cache.get(task.ID, f.ID); ok {
438				if v {
439					relevant[f.ID] = struct{}{}
440				}
441				continue
442			}
443			uncached = append(uncached, f)
444		}
445		if len(uncached) == 0 {
446			return relevant, nil
447		}
448		out, err := run(ctx, repoDir, judgeArgs, judgeInput(task.Task, uncached), defaultDistillTimeout)
449		if err != nil {
450			return nil, fmt.Errorf("judge task %s: %w", task.ID, err)
451		}
452		judged := parseJudgeOutput(out, uncached)
453		for _, f := range uncached {
454			_, isRel := judged[f.ID]
455			cache.set(task.ID, f.ID, isRel)
456			if isRel {
457				relevant[f.ID] = struct{}{}
458			}
459		}
460		return relevant, nil
461	}
462	
463	func printEvalSummary(cmd *cobra.Command, s evalSummary) {
464		out := cmd.OutOrStdout()
465		fmt.Fprintf(out, "%-14s %8s %7s %7s %9s\n", "task", "tokens", "prec", "recall", "useful/1k")
466		rows := append([]evalTaskResult(nil), s.Results...)
467		sort.SliceStable(rows, func(i, j int) bool { return rows[i].ID < rows[j].ID })
468		for _, r := range rows {
469			recall := "-"
470			if r.Labeled {
471				recall = fmt.Sprintf("%.2f", r.Recall)
472			}
473			fmt.Fprintf(out, "%-14s %8d %7.2f %7s %9.2f\n", truncateString(r.ID, 14), r.Tokens, r.Precision, recall, r.UsefulPer1k)
474		}
475		fmt.Fprintf(out, "%-14s %8.0f %7.2f %7s %9.2f\n", "MEAN", s.MeanTokens, s.MeanPrecision, "", s.MeanUsefulPer1k)
476		if len(s.ByStratum) > 0 {
477			fmt.Fprintf(out, "\n%-14s %8s %7s %7s %9s\n", "stratum", "tokens", "prec", "tasks", "useful/1k")
478			strata := make([]string, 0, len(s.ByStratum))
479			for qt := range s.ByStratum {
480				strata = append(strata, qt)
481			}
482			sort.Strings(strata)
483			for _, qt := range strata {
484				st := s.ByStratum[qt]
485				fmt.Fprintf(out, "%-14s %8.0f %7.2f %7d %9.2f\n", qt, st.MeanTokens, st.MeanPrecision, st.Tasks, st.MeanUsefulPer1k)
486			}
487		}
488	}
