func runBrainHandoff(ctx context.Context, cmd *cobra.Command, opts Options, sessionCount int, jsonOut bool) error {
	_, brainDir, branch, err := resolveFactsTarget(ctx, opts, agentSurfaceTarget(opts, nil), "")
	if err != nil {
