	get := func(path string) *sessionRecords {
		sr, ok := byPath[path]
		if !ok {
			sr = &sessionRecords{}
			byPath[path] = sr
		}
		return sr
	}
	for _, r := range index.Records {
		switch r.Kind {
		case "request":
			// The session's opening request is the request record with the
			// lowest line number; later requests are mid-session follow-ups.
			sr := get(r.Path)
			if sr.request == "" || r.Line < sr.requestLine {
				sr.request, sr.requestLine = r.Summary, r.Line
			}
		case "decision":
			get(r.Path).decisions = append(get(r.Path).decisions, r)
		case "validation":
			get(r.Path).validations = append(get(r.Path).validations, r)
		}
	}

