89			},
90		}
91		cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit machine-readable JSON")
92		cmd.Flags().StringVar(&branch, "branch", "", "Branch for facts (default: current)")
93		return cmd
94	}
