    {
      "info": {"role": "assistant"},
      "parts": [{"type": "text", "text": "Hello"}]
    },
    {
      "info": {"role": "user"},
      "parts": [{"type": "text", "text": "Remove the header bottom border"}]
    }
  ]
}`
	if got := firstUserRequest(doc); got != "Remove the header bottom border" {
		t.Errorf("firstUserRequest(opencode document) = %q", got)
	}
}

